interface ChannelOrderItem {
  channelSku: string;
  qty: number;
  paidLineAmountVnd: number;
}

interface MisaInvoiceLine {
  accountingSku: string;
  qty: number;
  unitPriceBeforeVat: number;
  vatRate: 8 | 10;
  isPromoZeroPrice: boolean;
}

export async function processEcommerceOrderToMisa(
  db: DbTransactionClient,
  payload: {
    channel: 'SHOPEE' | 'TIKTOK' | 'WEB';
    externalOrderId: string;
    paymentStatus: 'UNPAID_COD' | 'PAID_VIETQR' | 'SETTLED_PLATFORM';
    orderState: 'CONFIRMED' | 'CANCELLED' | 'RETURNED_PARTIAL' | 'DELIVERED';
    buyerTaxCode?: string;
    items: ChannelOrderItem[];
  }
) {
  const idempotencyKey = `${payload.channel}:${payload.externalOrderId}`;
  const existing = await db.orders.findByIdempotencyKey(idempotencyKey);

  const misaLines: MisaInvoiceLine[] = [];
  for (const item of payload.items) {
    const bomComponents = await db.skuMappings.resolveBundleOrSingle(payload.channel, item.channelSku);
    if (!bomComponents.length) {
      await db.alerts.notifyZaloOps(`SKU chưa map MISA: ${payload.channel}/${item.channelSku}`);
      throw new Error(`UNMAPPED_CHANNEL_SKU:${item.channelSku}`);
    }
    for (const comp of bomComponents) {
      const neededQty = comp.ratio * item.qty;
      if (!existing && payload.orderState === 'CONFIRMED') {
        await db.inventory.atomicReserveStock(comp.accountingSku, neededQty, idempotencyKey);
      }
      misaLines.push({
        accountingSku: comp.accountingSku,
        qty: neededQty,
        unitPriceBeforeVat: comp.isGift ? 0 : Math.round(comp.allocatedPrice / (1 + comp.vatRate / 100)),
        vatRate: comp.vatRate,
        isPromoZeroPrice: comp.isGift,
      });
    }
  }

  const eligibleForVat = payload.orderState === 'DELIVERED' || payload.paymentStatus === 'PAID_VIETQR';
  if (!eligibleForVat) {
    return { status: 'HELD_AT_STATE_GATE', idempotencyKey, reservedLines: misaLines.length };
  }

  return db.misaOutbox.enqueueIdempotent({
    idempotencyKey,
    taxCode: payload.buyerTaxCode ?? null,
    lines: misaLines,
    callbackHook: '/api/crm/misa-invoice-callback',
  });
}
